mapper.select:
select r.id, r.post_id, r.member_id, r.del_flag, r.create_time, m.nickname as nickname, m.avatar as avatar
from club_post_repost r
left join ums_member m on m.id = r.member_id
where r.del_flag = 0
  and r.member_id in (
      select cm.member_id from club_member cm
      join club c on c.id = cm.club_id and c.del_flag = 0
      where cm.status = 1 and cm.del_flag = 0
        and cm.club_id in
        #{cid}
  )
   and r.create_time >= #{since}
   and r.create_time < #{until}
order by r.create_time desc, r.id desc
limit #{limit}
